import com.truckload.controller.*;
public class SessionPolicyTest {
 static int n;static void check(boolean b){n++;if(!b)throw new AssertionError("Session check "+n);}
 public static void main(String[] args){Telemetry m=new Telemetry();m.sensor="READY";m.psi=20;m.points=1;
 check(SessionPolicy.capture(m,true,5000,2000,2000));check(!SessionPolicy.capture(m,false,5000,2000,2000));check(!SessionPolicy.capture(m,true,5000,0,2000));check(!SessionPolicy.capture(m,true,5000,999,2000));check(!SessionPolicy.capture(m,true,5000,2000,999));m.bench=true;check(!SessionPolicy.capture(m,true,5000,2000,2000));m.bench=false;m.psi=Double.NaN;check(!SessionPolicy.capture(m,true,5000,2000,2000));m.psi=20;m.points=8;check(!SessionPolicy.capture(m,true,5000,2000,2000));
 for(String s:new String[]{"OFF","NO_SIGNAL","STALE","SETTLING","UNSTABLE"}){m.sensor=s;check(!SessionPolicy.capture(m,true,5000,2000,2000));}
 check(SessionPolicy.retryDelay(0)==2000);check(SessionPolicy.retryDelay(1)==8000);check(SessionPolicy.retryDelay(2)==20000);check(SessionPolicy.retryDelay(3)==-1);check(SessionPolicy.retryDelay(99)==-1);
 check(SessionPolicy.separated(Double.NaN,20));check(!SessionPolicy.separated(20,21.9));check(SessionPolicy.separated(20,22));check(!SessionPolicy.separated(20,Double.NaN));
 m=new Telemetry();check(SessionPolicy.compatibility(m).contains("Limited"));m.apply("CAPS|2|DRIVING,BENCH,MAP");check(m.extended&&!m.capabilities.contains("BENCH_ZONES"));check(SessionPolicy.compatibility(m).contains("Limited"));m.apply("CAPS|3|DRIVING,BENCH,MAP,BENCH_ZONES,BENCH_COLOR,ADC_RAW,FW_INFO");check(m.extended&&SessionPolicy.compatibility(m).startsWith("Compatible"));m.apply("FW_INFO|0.6.2|board|43|44");check(m.firmware.equals("0.6.2"));m.apply("SENSOR|ON|READY|0.700|1.018|1000");check(m.rawAdc==1000);m.apply("SENSOR|ON|READY|0.700|1.018");check(m.rawAdc==-1);m.apply("SENSOR|ON|READY|0.700|1.018|5000");check(m.rawAdc==-1);m.apply("BENCH_STATE|1|DRIVE|90|35|0|2|RED");check(m.bench&&m.benchZone.equals("2")&&m.benchColor.equals("RED"));m.apply("BENCH_STATE|0|LOAD|50|25|0");check(!m.bench&&m.benchZone.equals("BOTH"));m.apply("CAPS|2|MAP");check(!m.extended);System.out.println("PASS: "+n+" safety, compatibility and extended diagnostics checks");}
}
